// Illustrative cell-to-DNA scale tour. Condensed chromosome is packaging context,
// not a claim that a mitotic chromosome is being transcribed. No atomic data.
export default scene({mode:'3d',orbit:false,end:'advance',background:Color.PURPLE_E},s=>{
 const PI=Math.PI, TAU=2*PI;
 const sample=(f,a,b,n)=>Array.from({length:n+1},(_,i)=>f(a+(b-a)*i/n));
 const satin={roughness:.73,specular:.28,metalness:.04};
 const pink={fill:Color.PINK,texture:{pattern:'noise',color:Color.PURPLE_A,scale:9,seed:13,bumpStrength:.002},material:satin};
 const violet={fill:Color.PURPLE_C,texture:{pattern:'noise',color:Color.PURPLE_D,scale:5,seed:27,bumpStrength:.003},material:satin};
 const back={fill:Color.GREY_C,texture:{pattern:'noise',color:Color.GREY_D,scale:.16,seed:12,bumpStrength:.001},material:{roughness:.62,specular:.32,emissive:Color.PURE_BLUE,emissiveIntensity:.07}};
 const colors={A:Color.GREEN,T:Color.RED,C:Color.BLUE_A,G:Color.YELLOW_D};
 const camera=(height,distance,target,yaw=.12,pitch=.06)=>s.camera.to3D({height,distance,target,yaw,pitch});
 s.play(camera(18,36,[0,0,0],.15,.1),{duration:0});
 // Layered palette geometry approximates a soft atmospheric gradient.
 s.mesh('cell-atmosphere',{vertices:[[-60,-55,-15],[60,-55,-15],[60,55,-15],[-60,55,-15]],triangles:[[0,1,2],[0,2,3]],shading:'unlit',fill:Color.PURPLE_D});
 // Nonintersecting horizontal strips avoid transparent triangle sorting seams.
 for(let i=0;i<64;i++){const y=-24+i*.75;const alpha=.08+.55/(1+Math.exp((y+1)/4));s.rectangle('cell-atmosphere-gradient-'+i,{position:[0,y,-12],width:80,height:.76,fill:{color:Color.BLUE_A,opacity:alpha},stroke:Color.NONE});}
 function localLabel(id,text,p,to,size=.4){const t=s.text(id,{text,position:p,billboard:true,fontSize:size,fill:Color.WHITE});const l=s.line(id+'-leader',{points:[[p[0],p[1]-.24,p[2]],to],stroke:{color:Color.WHITE,opacity:.7},strokeWidth:.018});return s.group(id+'-annotation',[t,l]);}
 // du cross dv points outward by reversing the azimuth.
 function cellPoint(u,v,r){u=-u;const sv=Math.sin(v),bulge=1+.035*Math.sin(3*u+.6)*sv*sv+.024*Math.cos(5*u-2*v)*sv;return[r*sv*Math.cos(u)*bulge,r*.94*sv*Math.sin(u)*bulge,r*.83*Math.cos(v)*bulge];}
 const shell=s.parametricSurface('cell-posterior-membrane',{uRange:[0,TAU],vRange:[PI/2,PI],closedU:true,uSegments:28,vSegments:10,fn:(u,v)=>cellPoint(u,v,6),...pink});
 const cap=s.parametricSurface('cell-anterior-membrane',{uRange:[0,TAU],vRange:[0,PI/2],closedU:true,uSegments:28,vSegments:12,fn:(u,v)=>cellPoint(u,v,6),...pink});
 const cut=s.tube('cell-cut-edge',{points:sample(u=>cellPoint(u,PI/2,6),0,TAU,110),radius:.095,radialSegments:6,closed:true,fill:Color.LIGHT_PINK,material:satin});
 const nucleus=s.sphere('nucleus-envelope',{position:[-.65,.1,-.45],radius:2.45,...violet});
 const organelles=[shell,cut,nucleus];
 // Broad nested folded endoplasmic-reticulum sheets wrap around the nucleus.
 for(let k=0;k<6;k++){
  const r=2.72+.32*k,from=-.2+.1*Math.sin(k),to=4.55+.1*Math.cos(k);
  const er=s.parametricSurface('er-fold-'+k,{uRange:[from,to],vRange:[-.28,.28],uSegments:24,vSegments:2,fn:(u,v)=>{const rr=r+v+.13*Math.sin(6*u+k*.8);return[-.65+rr*Math.cos(u),.1+rr*.73*Math.sin(u),-.15+.32*Math.sin(5*u+k)+.95*v];},...pink});organelles.push(er);
  organelles.push(s.tube('er-rim-'+k,{points:sample(u=>{const rr=r+.28+.13*Math.sin(6*u+k*.8);return[-.65+rr*Math.cos(u),.1+rr*.73*Math.sin(u),.116+.32*Math.sin(5*u+k)];},from,to,32),radius:.048,radialSegments:6,fill:Color.LIGHT_PINK,material:satin}));
 }
 // Sectioned elongated mitochondria: an occupied back body and visible cristae.
 function mitochondrion(id,p,angle){const kids=[];function point(x,y,z){return[p[0]+x*Math.cos(angle)-y*Math.sin(angle),p[1]+x*Math.sin(angle)+y*Math.cos(angle),p[2]+z];}
  kids.push(s.parametricSurface(id+'-body',{uRange:[0,TAU],vRange:[PI/2,PI],closedU:true,uSegments:22,vSegments:10,fn:(u,v)=>point(1.1*Math.sin(v)*Math.cos(-u),.47*Math.sin(v)*Math.sin(-u),.40*Math.cos(v)),fill:Color.RED_C,texture:{pattern:'noise',color:Color.LIGHT_PINK,scale:3,seed:35,bumpStrength:.002},material:satin}));
  kids.push(s.tube(id+'-lip',{points:sample(u=>point(1.1*Math.cos(u),.47*Math.sin(u),0),0,TAU,50),closed:true,radius:.052,radialSegments:6,fill:Color.LIGHT_PINK,material:satin}));
  for(let j=0;j<6;j++)kids.push(s.tube(id+'-crista-'+j,{points:sample(q=>point(-.8+j*.30+.075*Math.sin(q*PI),q*.36,-.13+.10*Math.cos(q*PI)), -1,1,12),radius:.058,radialSegments:6,fill:Color.PINK,material:satin}));return s.group(id,kids);
 }
 organelles.push(mitochondrion('mitochondrion-left',[-3.7,-2.7,.6],-.45));
 organelles.push(mitochondrion('mitochondrion-right',[3.8,1.55,.4],.8));
 organelles.push(mitochondrion('mitochondrion-low',[2.8,-3.2,.3],.35));
 const cellLabel=localLabel('cell-label','Cell',[3.65,3.85,4],[2.9,2.7,4.7],.5);
 // 0–8: substantial forward approach, without decorative spinning.
 s.play(camera(14,28,[0,0,0],.16,.09),{duration:7,ease:'smooth'});
 s.play(cellLabel.fadeOut(),{duration:1});s.remove(cellLabel);
 // 8–10: remove the forward hemisphere, exposing rather than occluding anatomy.
 s.play([cap.fadeOut(),camera(12.8,25,[-.2,0,0],.15,.08)],{duration:2,ease:'smooth'});s.remove(cap);
 const nucleusLabel=localLabel('nucleus-label','Nucleus',[.65,2.9,2.2],[-.1,1.5,1.9],.4);
 s.wait(2);
 s.play(camera(9.1,20,[-.6,.1,0],.13,.06),{duration:4,ease:'smooth'});
 s.play(nucleusLabel.fadeOut(),{duration:1});s.remove(nucleusLabel);s.wait(1);
 // 18–24: an explicit nuclear cutaway reveals chromatin before the camera enters.
 const chromatin=[];
 for(let j=0;j<5;j++)chromatin.push(s.tube('nuclear-chromatin-'+j,{points:sample(t=>[-.65+1.65*Math.sin(2.1*t+j*.64)*Math.cos(.42*t),.1+1.68*Math.sin(1.37*t+j*.8),-.2+.84*Math.cos(1.7*t+j*.65)],0,5.1,40),radius:.045,radialSegments:6,...violet}));
 const threads=s.group('nuclear-chromatin',chromatin);
 const rearNucleus=s.parametricSurface('nucleus-rear-cutaway',{uRange:[0,TAU],vRange:[PI/2,PI],closedU:true,uSegments:32,vSegments:14,fn:(u,v)=>[-.65+2.45*Math.sin(v)*Math.cos(-u),.1+2.45*Math.sin(v)*Math.sin(-u),-.45+2.45*Math.cos(v)],...violet});
 s.play([nucleus.fadeOut(),camera(6.4,16,[-.65,.1,0],.10,.05)],{duration:2,ease:'smooth'});s.remove(nucleus);
 s.play(camera(4.8,13,[-.65,.1,.1],.06,.03),{duration:3,ease:'smooth'});
 s.play([...organelles.filter(x=>x!==nucleus).map(x=>x.fadeOut()),rearNucleus.fadeOut()],{duration:1});for(const x of organelles.filter(x=>x!==nucleus))s.remove(x);s.remove(rearNucleus);
 // 24–30: illustrative condensed packaging. Each chromatid is a continuous
 // curved lobular surface with narrowed waist; two chromatids meet centrally.
 const chromatid=[];
 for(let side=0;side<2;side++)chromatid.push(s.parametricSurface('chromatid-'+side,{uRange:[0,TAU],vRange:[0,PI],closedU:true,uSegments:22,vSegments:22,fn:(u,v)=>{u=-u;const y=2.6*Math.cos(v),waist=.35+.30*Math.pow(Math.abs(Math.cos(v)),.6);const r=waist*Math.sin(v)*(1+.06*Math.sin(7*u+10*v));const x=(side?1:-1)*(.20+.67*Math.pow(Math.abs(y/2.6),1.25));return[x+r*Math.cos(u),y+.045*Math.sin(5*u)*Math.sin(v),r*.90*Math.sin(u)];},...violet}));
 const chromosome=s.group('condensed-chromosome',chromatid);
 s.play([chromosome.fadeIn(),threads.fadeOut(),camera(7.2,21,[0,0,0],.20,.11)],{duration:2,ease:'smooth'});s.remove(threads);
 const chromosomeLabel=localLabel('chromosome-label','Chromosome',[2.3,1.8,.5],[.9,1.1,.45],.34);
 s.wait(3);s.play(chromosomeLabel.fadeOut(),{duration:1});s.remove(chromosomeLabel);
 // 30–38: scale follows the emerging connected fibre into nucleosomes.
 s.play([chromosome.scaleTo(.47),chromosome.moveTo([-5.7,.25,-1.8]),camera(8.5,27,[-.7,0,0],.15,.07)],{duration:2,ease:'smooth'});
 const packaging=[];
 packaging.push(s.tube('unpacked-chromatin-connection',{points:sample(t=>[-5.5+2.8*t,.3+.50*Math.sin(TAU*t),-1.6+1.6*t],0,1,56),radius:.095,radialSegments:6,...violet}));
 const histoneCenters=[[-2.2,.65,0],[.2,-.65,.2],[2.6,.65,.1]];
 let last=[-2.7,.3,0];
 for(let k=0;k<histoneCenters.length;k++){
  const p=histoneCenters[k];
  packaging.push(s.cylinder('histone-core-'+k,{position:p,radius:.65,height:.86,radialSegments:28,fill:Color.GOLD_D,texture:{pattern:'noise',color:Color.GOLD_C,scale:3,seed:41,bumpStrength:.002},material:satin}));
  // DNA wraps twice around the Y axis of each flattened gold core.
  const wrap=sample(t=>[p[0]+.76*Math.cos(t),p[1]-.37+.74*t/(4*PI),p[2]+.76*Math.sin(t)],0,4*PI,64);
  packaging.push(s.tube('histone-link-'+k,{points:sample(t=>[last[0]+(wrap[0][0]-last[0])*t,last[1]+(wrap[0][1]-last[1])*t+.18*Math.sin(PI*t),last[2]+(wrap[0][2]-last[2])*t],0,1,15),radius:.075,radialSegments:6,...back}));
  packaging.push(s.tube('histone-wrapped-DNA-'+k,{points:wrap,radius:.075,radialSegments:6,...back}));last=wrap[wrap.length-1];
 }
 packaging.push(s.tube('histone-to-helix-link',{points:sample(t=>[last[0]+4.2*t,last[1]+.5*t,last[2]+.3*Math.sin(PI*t)],0,1,30),radius:.075,radialSegments:6,...back}));
 const packageGroup=s.group('histone-packaging',packaging);
 s.play(packageGroup.fadeIn(),{duration:1});
 const histoneLabel=localLabel('histone-label','Histone',[.15,1.7,1.0],[.2,-.25,.5],.36);
 s.play(camera(7.2,24,[.6,.2,0],.16,.1),{duration:3,ease:'smooth'});
 s.play(histoneLabel.fadeOut(),{duration:.6});s.remove(histoneLabel);

 // 38–44: generous oblique double helix, exact endpoint documented for handoff.
 const dna=[];const strand=(x,phase)=>[x,.30*x+1.1*Math.cos(1.3*x+phase),1.1*Math.sin(1.3*x+phase)];
 for(let j=0;j<2;j++)dna.push(s.tube('overview-DNA-backbone-'+j,{points:sample(x=>strand(x,j*PI),-12,12,145),radius:.13,radialSegments:6,...back}));
 const seq=['A','G','C','T','G','A','C','A','T','G'];
 for(let i=0;i<51;i++){const x=-12+i*.48,a=strand(x,0),b=strand(x,PI),m=a.map((v,j)=>(v+b[j])/2),base=seq[i%seq.length],comp={A:'T',T:'A',G:'C',C:'G'}[base];for(let j=0;j<2;j++)dna.push(s.tube('overview-DNA-base-'+i+'-'+j,{points:j?[m,b]:[a,m],radius:.075,radialSegments:6,capped:true,fill:colors[j?comp:base],material:satin}));}
 const helix=s.group('overview-DNA',dna);
 // First the small outgoing helix remains attached to the packaging context;
 // a continuous enlargement brings this same helix into the final close view.
 s.play([helix.scaleTo(.28),helix.moveTo([10.9,1.68,0])],{duration:0});
 s.play(helix.fadeIn(),{duration:.4});
 s.play([helix.scaleTo(1),helix.moveTo([0,0,0]),chromosome.fadeOut(),packageGroup.fadeOut(),camera(11.5,32,[0,0,0],.12,.06)],{duration:3,ease:'smooth'});s.remove(chromosome);s.remove(packageGroup);
 const dnaLabel=localLabel('dna-label','DNA',[.4,2.6,1.1],[0,1.1,0],.44);s.wait(2.8);s.play(dnaLabel.fadeOut(),{duration:.7});s.remove(dnaLabel);s.wait(.5);
});
